(132, '10_3', 720, 440, NULL, '[152]', 'The Torched Courts', 'Pious priests once dealt cruel justice within these halls, now they both smoulder in silent agony.', '[1540]', 10, '10_3', '[1541]', NULL, NULL),
(133, '10_4', 660, 505, 153, '[153]', 'The Desecrated Chambers', 'Mad men toil under smoking skies to pervert a holy sanctum.', '[1541]', 10, '10_4', '[1542]', NULL, NULL),
(134, '10_5', 640, 223, NULL, '[154]', 'The Canals', 'A man-made rupture from which both blood and water flow.', '[1540]', 10, '10_5', '[1543]', NULL, NULL),
(135, '10_6', 750, 215, NULL, '[155]', 'The Feeding Trough', 'Cries of torment and pathetic moans as the unholy banquet of flesh continues.', '[1543]', 10, '10_6', '[1544]', NULL, NULL),
(136, '10_7', 230, 350, 156, '[156]', 'The Control Blocks', 'Sadists and cut-throats break both bone and brain.', '[1540]', 10, '10_7', '[1545]', NULL, NULL),
(137, '10_8', 326, 418, 157, '[157]', 'The Reliquary', 'Empty, broken shelves linger, looted and forgotten in the wake of this horrid war.', '[1540]', 10, '10_8', '[1546]', NULL, NULL),
(138, '10_9', 687, 150, NULL, '[158]', 'The Ossuary', 'The dead offer thanks, for they have been spared this final savagery.', '[1540]', 10, '10_9', '[1547]', NULL, NULL),
(139, '11_town2', 781, 354, 167, '[167]', 'Karui Shores', 'The fates of two peoples now stand reversed, but history has taught the Oriathans humility and the Karui mercy.', '[]', 11, '11_town2', '[1548]', NULL, NULL);
